'use strict';
// Records are derived from saved pregame forecasts, never current predictions.
const DarkhorseResults = (() => {
  const markets = {winner:'Moneyline',spread:'Point spread',total:'Over / under',upset:'Outright upsets'};
  const descriptions = {winner:'Did we pick the winning team?',spread:'Did our side beat the point spread?',total:'Did we pick the right side of the combined score?',upset:'Did our underdog pick win the game?'};
  const easternDate = value => new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
  function weekOf(value){const d=new Date(easternDate(value)+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10);}
  function outcome(row,key){return key==='upset'?row.upsetPickResult:row[key];}
  function tally(rows,key){const counts={win:0,loss:0,push:0,no_pick:0,unavailable:0};for(const row of rows){const v=outcome(row,key);if(v in counts)counts[v]++;}return counts;}
  function filter(rows,period,conference,query,teams){return rows.filter(r=>(period==='all'||(period.startsWith('week:')?weekOf(r.date)===period.slice(5):easternDate(r.date)===period.slice(4)))&&(conference==='all'||[r.home,r.away].some(t=>teams[t]?.conference===conference))&&(!query||[r.home,r.away].some(t=>(teams[t]?.name||t).toLowerCase().includes(query.toLowerCase()))));}
  const api={tally,filter,weekOf,easternDate};
  if(typeof module!=='undefined')module.exports=api;
