  function ledger(rows){const chosen=market==='upset'?rows.filter(r=>r.pickedUnderdog):rows;const labels={win:'Correct',loss:'Missed',push:'Push',no_pick:'No pick',unavailable:'No saved line'};
    $('prLedger').innerHTML=chosen.length?chosen.slice(0,limit).map(r=>{const result=outcome(r,market);return `<div class="pr-receipt"><div><small>${niceDate(easternDate(r.date))} · ${esc(shortConf(D.teams[r.home]?.conference||''))}</small><h4>${rankedMatchup(r,true)}</h4><p>Our pick: <b>${esc(selection(r,market))}</b></p><p class="pr-score">Final: ${esc(score(r))}${market==='total'?' · '+(r.homeScore+r.awayScore)+' total points':''}</p><details><summary>Saved pick & line</summary><p>Forecast: ${esc(stamp(r.forecastAt))}. ${r.archiveType==='recovered_saved_forecast'?'Recovered saved forecast.':'Daily archived forecast.'}</p><p>Model: ${r.pickedTeam?esc(name(r.pickedTeam))+' by '+Math.abs(r.predictedHomeMargin).toFixed(1):'Even'} · ${r.predictedTotal.toFixed(1)} combined points.</p><p>${r.quoteRetrievedAt?'Line checked '+esc(stamp(r.quoteRetrievedAt))+(r.quoteProvider?' · '+esc(r.quoteProvider):'')+'.':'No eligible pregame line saved.'}</p><a href="${esc(r.sourceArchive)}" target="_blank" rel="noreferrer">View saved forecast ↗</a></details></div><span class="pr-outcome ${result}">${labels[result]||'Not graded'}</span></div>`;}).join(''):'<p class="pr-empty">No saved picks match these filters.</p>';
    $('prMore').hidden=chosen.length<=limit;$('prMore').textContent=`Show more picks (${Math.min(limit,chosen.length)} of ${chosen.length})`;
